import numpy as np
from collections import deque

def f2(g, mincells=3):
    a=np.array(g); H,W=a.shape
    bg=Counter(a.ravel()).most_common(1)[0][0]
    res=a.copy(); keep=np.zeros_like(a,bool)
    for c in range(10):
        if c==bg: continue
        mask=a==c
        if not mask.any(): continue
        # closing: dilate then erode with 3x3 to bridge 1-px gaps
        def dil(m):
            m2=m.copy()
            m2[1:,:]|=m[:-1,:]; m2[:-1,:]|=m[1:,:]; m2[:,1:]|=m[:,:-1]; m2[:,:-1]|=m[:,1:]
            return m2
        def ero(m):
            m2=m.copy()
            m2[1:,:]&=m[:-1,:]; m2[:-1,:]&=m[1:,:]; m2[:,1:]&=m[:,:-1]; m2[:,:-1]&=m[:,1:]
            return m2
        closed=dil(ero(mask))|mask if False else ero(dil(mask))|mask
        # components on closed
        seen=np.zeros_like(mask); 
        for i in range(H):
            for j in range(W):
                if closed[i,j] and not seen[i,j]:
                    q=deque([(i,j)]); seen[i,j]=True; cells=[]
                    while q:
                        y,x=q.popleft(); cells.append((y,x))
                        for dy in(-1,0,1):
                            for dx in(-1,0,1):
                                ny,nx=y+dy,x+dx
                                if 0<=ny<H and 0<=nx<W and closed[ny,nx] and not seen[ny,nx]:
                                    seen[ny,nx]=True; q.append((ny,nx))
                    orig=[p for p in cells if mask[p]]
                    if len(orig)>=mincells:
                        ys=[p[0] for p in orig]; xs=[p[1] for p in orig]
                        for y in range(min(ys),max(ys)+1):
                            for x in range(min(xs),max(xs)+1):
                                keep[y,x]=True; res[y,x]=c
    for i in range(H):
        for j in range(W):
            if not keep[i,j]: res[i,j]=bg
    return res.tolist()

